out.push("\n\n### 11.2 HTML 实现\n\n可以在 Shopify `layout/theme.liquid` 中、`body` 结束之前添加全局消息区域。\n\n```html\n<div id=\"a11y-announcer\">\n\n  <div\n    data-announcer=\"polite\"\n    role=\"status\"\n    aria-atomic=\"true\"\n    class=\"visually-hidden\"\n  ></div>\n\n  <div\n    data-announcer=\"assertive\"\n    role=\"alert\"\n    class=\"visually-hidden\"\n  ></div>\n\n</div>\n```\n\n这两个区域在页面初始化时就存在，并且不应该被常规 Section Rendering 替换。\n\n需要独立通知的模态弹窗，可以在自己的内部建立同样的结构。\n\n### 11.3 JavaScript 工具类\n\n创建 `assets/accessibility-announcer.js`：\n\n```javascript\nclass AccessibilityAnnouncer {\n  constructor(container) {\n    this.regions = {\n      polite: container.querySelector(\n        '[data-announcer=\"polite\"]'\n      ),\n\n      assertive: container.querySelector(\n        '[data-announcer=\"assertive\"]'\n      )\n    };\n\n    this.timers = {\n      polite: null,\n      assertive: null\n    };\n  }\n\n  announce(message, {\n    priority = 'polite',\n    delay = 100\n  } = {}) {\n    const region = this.regions[priority];\n\n    if (!region || !message?.trim()) {\n      return;\n    }\n\n    clearTimeout(this.timers[priority]);\n\n    region.textContent = '';\n\n    this.timers[priority] = setTimeout(() => {\n      if (region.isConnected) {\n        region.textContent = message;\n      }\n\n      this.timers[priority] = null;\n    }, delay);\n  }\n\n  success(message) {\n    this.announce(message);\n  }\n\n  error(message) {\n    this.announce(message, {\n      priority: 'assertive'\n    });\n  }\n\n  clear(priority) {\n    const region = this.regions[priority];\n\n    if (!region) return;\n\n    clearTimeout(this.timers[priority]);\n\n    this.timers[priority] = null;\n\n    region.textContent = '';\n  }\n\n  destroy() {\n    this.clear('polite');\n    this.clear('assertive');\n  }\n}\n```\n\n初始化：\n\n```javascript\nconst announcer = new AccessibilityAnnouncer(\n  document.querySelector('#a11y-announcer')\n);\n```\n\n业务组件中使用：\n\n```javascript\nannouncer.success(\n  'Product added to your cart.'\n);\n```\n\n```javascript\nannouncer.error(\n  'Unable to update your cart.'\n);\n```\n\n### 11.4 交互实验\n\n");
