out.push("\n\n因此，Live Region 不仅需要正确的 ARIA 属性，还需要正确的异步请求管理。\n\n```javascript\nlet requestVersion = 0;\nlet controller;\n\nasync function updateCollection(url) {\n  const version = ++requestVersion;\n\n  controller?.abort();\n\n  controller = new AbortController();\n\n  const grid = document.querySelector(\n    '#ProductGridContainer'\n  );\n\n  const count = document.querySelector(\n    '#ProductCount'\n  );\n\n  grid.setAttribute('aria-busy', 'true');\n\n  try {\n    const response = await fetch(url, {\n      signal: controller.signal\n    });\n\n    if (!response.ok) {\n      throw new Error('Request failed');\n    }\n\n    const html = new DOMParser().parseFromString(\n      await response.text(),\n      'text/html'\n    );\n\n    if (version !== requestVersion) return;\n\n    const newGrid = html.querySelector(\n      '#ProductGridContainer'\n    );\n\n    const newCount = html.querySelector(\n      '#ProductCount'\n    );\n\n    if (!newGrid || !newCount) {\n      throw new Error('Invalid section response');\n    }\n\n    grid.innerHTML = newGrid.innerHTML;\n\n    // 保留原来的 Live Region 节点\n    count.textContent = newCount.textContent.trim();\n\n  } catch (error) {\n    if (\n      error.name !== 'AbortError' &&\n      version === requestVersion\n    ) {\n      announcer.error(\n        'Unable to update products.'\n      );\n    }\n\n  } finally {\n    if (version === requestVersion) {\n      grid.setAttribute('aria-busy', 'false');\n    }\n  }\n}\n```\n\n这个例子假设传入的 URL 返回包含对应商品区域和数量区域的 HTML。\n\n它展示了三个重要的工程机制：取消旧请求、校验最新请求版本、保留 Live Region 节点。\n\n实际开发中还需要接入上一课的 Focus Preservation，尤其是在筛选操作同时替换筛选控件 DOM 的情况下。\n\n---\n\n## 15. Shopify 实战四：Predictive Search\n\nPredictive Search 同时涉及我们第三阶段学习的多种技术。\n\n| 技术 | 职责 |\n|---|---|\n| `role=\"combobox\"` | 表达搜索组合控件 |\n| `aria-expanded` | 表达建议列表展开状态 |\n| `aria-controls` | 关联建议列表 |\n| `aria-activedescendant` | 表达当前活动建议 |\n| `aria-selected` | 根据组件模式表达选项状态 |\n| Live Region | 通知搜索结果数量 |\n\n");
